<?php namespace App\Services;
final class ReportService { public function __construct(private \PDO $db) {} public function monthly(array $user):array {$where=$user['role']==='student'?'WHERE s.user_id=?':'';$sql="SELECT u.full_name,s.student_no,COUNT(a.id) attended,COUNT(DISTINCT x.id) classes_conducted,ROUND(CASE WHEN COUNT(DISTINCT x.id)=0 THEN 0 ELSE COUNT(a.id)*100/COUNT(DISTINCT x.id) END,2) attendance_percentage FROM students s JOIN users u ON u.id=s.user_id LEFT JOIN attendance a ON a.student_id=s.id LEFT JOIN attendance_sessions x ON x.id=a.session_id {$where} GROUP BY s.id ORDER BY u.full_name";$s=$this->db->prepare($sql);$s->execute($where?[$user['id']]:[]);return ['report'=>$s->fetchAll()];} }
